/* Auto-generated Cana logo for Zebra labels (^GFA / ^DG+^XG) */
const CANA_LOGO_ZPL = {
  small: { widthDots: 160, heightDots: 130, bytesPerRow: 20, totalBytes: 2600, hex: '' },
  med: { widthDots: 220, heightDots: 178, bytesPerRow: 28, totalBytes: 4984, hex: '' }
};
const CANA_LOGO_IMG = 'assets/cana-logo.png';
/** Inline graphic once (for single-label test print). */
function buildCanaLogoGfa(x, y, sizeKey){
  const g = CANA_LOGO_ZPL[sizeKey] || CANA_LOGO_ZPL.small;
  return '^FO' + x + ',' + y + '^GFA,' + g.totalBytes + ',' + g.totalBytes + ',' + g.bytesPerRow + ',' + g.hex + '^FS\n';
}
/** Download graphic to printer memory once, then recall with ^XG — smaller multi-label ZPL. */
function buildCanaLogoDownloadCmd(sizeKey){
  const g = CANA_LOGO_ZPL[sizeKey] || CANA_LOGO_ZPL.small;
  const name = 'CANALOGO.GRF';
  return '~DGR:' + name + ',' + g.totalBytes + ',' + g.bytesPerRow + ',' + g.hex + '\n';
}
function buildCanaLogoRecall(x, y, sizeKey){
  const g = CANA_LOGO_ZPL[sizeKey] || CANA_LOGO_ZPL.small;
  return '^FO' + x + ',' + y + '^XGR:' + 'CANALOGO.GRF' + ',1,1^FS\n';
}
